import React, { useState, useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';

gsap?.registerPlugin(ScrollTrigger);

const VirtualTourSection = () => {
  const [activeHotspot, setActiveHotspot] = useState(null);
  const [currentTour, setCurrentTour] = useState('library');
  const sectionRef = useRef(null);
  const tourRef = useRef(null);

  const tourLocations = [
  {
    id: 'library',
    name: 'Digital Learning Library',
    image: "https://images.unsplash.com/photo-1615889944278-3aab1d57d543",
    alt: 'Modern library interior with students studying at wooden tables surrounded by floor-to-ceiling bookshelves',
    description: 'State-of-the-art digital library with over 100,000 resources and collaborative study spaces.',
    hotspots: [
    { id: 1, x: 25, y: 40, title: 'Digital Catalog Station', info: 'Access to global academic databases' },
    { id: 2, x: 60, y: 30, title: 'Quiet Study Pods', info: 'Individual soundproof study spaces' },
    { id: 3, x: 80, y: 60, title: 'Collaboration Zone', info: 'Group project and discussion areas' }]

  },
  {
    id: 'lab',
    name: 'Innovation Laboratory',
    image: "https://images.unsplash.com/photo-1668075955035-db1731d52cae",
    alt: 'High-tech computer laboratory with rows of modern workstations and large wall-mounted displays',
    description: 'Cutting-edge technology lab equipped with the latest hardware and software for hands-on learning.',
    hotspots: [
    { id: 1, x: 30, y: 35, title: 'Workstation Cluster', info: 'High-performance computing systems' },
    { id: 2, x: 70, y: 25, title: 'Interactive Displays', info: '4K smart boards for presentations' },
    { id: 3, x: 50, y: 70, title: 'Equipment Storage', info: 'VR headsets and specialized devices' }]

  },
  {
    id: 'auditorium',
    name: 'Main Auditorium',
    image: "https://images.unsplash.com/photo-1732775876055-3a6aaf17177e",
    alt: 'Large modern auditorium with tiered seating and professional stage lighting setup',
    description: 'Premium auditorium hosting lectures, seminars, and special events with advanced AV systems.',
    hotspots: [
    { id: 1, x: 50, y: 20, title: 'Main Stage', info: 'Professional presentation platform' },
    { id: 2, x: 20, y: 50, title: 'Tiered Seating', info: 'Comfortable seating for 300 students' },
    { id: 3, x: 80, y: 40, title: 'Control Booth', info: 'Advanced audio-visual controls' }]

  },
  {
    id: 'cafeteria',
    name: 'Student Cafeteria',
    image: "https://images.unsplash.com/photo-1686100509296-ad4240515e94",
    alt: 'Bright modern cafeteria with wooden tables, comfortable seating, and large windows providing natural light',
    description: 'Vibrant dining space offering healthy meals and social interaction opportunities.',
    hotspots: [
    { id: 1, x: 40, y: 45, title: 'Dining Area', info: 'Flexible seating arrangements' },
    { id: 2, x: 70, y: 30, title: 'Food Stations', info: 'Diverse cuisine options' },
    { id: 3, x: 15, y: 60, title: 'Lounge Zone', info: 'Casual meeting and relaxation space' }]

  }];


  useEffect(() => {
    const ctx = gsap?.context(() => {
      gsap?.fromTo(sectionRef?.current,
      { opacity: 0, y: 50 },
      {
        opacity: 1,
        y: 0,
        duration: 1,
        scrollTrigger: {
          trigger: sectionRef?.current,
          start: "top 80%",
          end: "bottom 20%",
          toggleActions: "play none none reverse"
        }
      }
      );

      gsap?.fromTo(".tour-card",
      { scale: 0.8, opacity: 0 },
      {
        scale: 1,
        opacity: 1,
        duration: 0.6,
        stagger: 0.1,
        scrollTrigger: {
          trigger: ".tour-grid",
          start: "top 85%",
          toggleActions: "play none none reverse"
        }
      }
      );
    }, sectionRef);

    return () => ctx?.revert();
  }, []);

  useEffect(() => {
    if (tourRef?.current) {
      gsap?.fromTo(tourRef?.current,
      { opacity: 0, scale: 0.95 },
      { opacity: 1, scale: 1, duration: 0.5 }
      );
    }
  }, [currentTour]);

  const currentLocation = tourLocations?.find((loc) => loc?.id === currentTour);

  return (
    <section ref={sectionRef} className="py-20 bg-gradient-to-br from-background via-card to-background">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-gradient mb-6">Virtual Campus Tour</h2>
          <p className="text-xl text-muted-foreground max-w-3xl mx-auto">
            Explore our state-of-the-art facilities from anywhere. Click on hotspots to discover interactive features and learning spaces designed for your success.
          </p>
        </div>

        {/* Tour Navigation */}
        <div className="tour-grid grid grid-cols-2 lg:grid-cols-4 gap-4 mb-12">
          {tourLocations?.map((location) =>
          <button
            key={location?.id}
            onClick={() => setCurrentTour(location?.id)}
            className={`tour-card p-4 rounded-xl border-2 transition-all duration-300 hover-lift ${
            currentTour === location?.id ?
            'border-primary bg-primary/10 shadow-brand-md' :
            'border-border bg-card hover:border-primary/50'}`
            }>

              <div className="aspect-video rounded-lg overflow-hidden mb-3">
                <Image
                src={location?.image}
                alt={location?.alt}
                className="w-full h-full object-cover" />

              </div>
              <h3 className="font-semibold text-sm text-center">{location?.name}</h3>
            </button>
          )}
        </div>

        {/* Main Tour Viewer */}
        <div className="bg-card rounded-2xl shadow-brand-lg overflow-hidden">
          <div ref={tourRef} className="relative aspect-video bg-muted">
            <Image
              src={currentLocation?.image}
              alt={currentLocation?.alt}
              className="w-full h-full object-cover" />

            
            {/* Interactive Hotspots */}
            {currentLocation?.hotspots?.map((hotspot) =>
            <button
              key={hotspot?.id}
              onClick={() => setActiveHotspot(activeHotspot === hotspot?.id ? null : hotspot?.id)}
              className="absolute w-8 h-8 bg-accent rounded-full border-4 border-white shadow-lg animate-pulse-glow hover:scale-110 transition-transform duration-200"
              style={{ left: `${hotspot?.x}%`, top: `${hotspot?.y}%` }}>

                <Icon name="Plus" size={16} color="white" className="mx-auto" />
              </button>
            )}

            {/* Hotspot Info Panel */}
            {activeHotspot &&
            <div className="absolute bottom-4 left-4 right-4 bg-background/95 backdrop-blur-sm rounded-lg p-4 shadow-brand-lg">
                {(() => {
                const hotspot = currentLocation?.hotspots?.find((h) => h?.id === activeHotspot);
                return (
                  <div className="flex items-start justify-between">
                      <div>
                        <h4 className="font-semibold text-foreground mb-1">{hotspot?.title}</h4>
                        <p className="text-sm text-muted-foreground">{hotspot?.info}</p>
                      </div>
                      <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => setActiveHotspot(null)}>

                        <Icon name="X" size={16} />
                      </Button>
                    </div>);

              })()}
              </div>
            }

            {/* Tour Controls */}
            <div className="absolute top-4 right-4 flex space-x-2">
              <Button variant="secondary" size="sm">
                <Icon name="Maximize2" size={16} className="mr-2" />
                Fullscreen
              </Button>
              <Button variant="secondary" size="sm">
                <Icon name="RotateCcw" size={16} className="mr-2" />
                360° View
              </Button>
            </div>
          </div>

          {/* Tour Information */}
          <div className="p-6">
            <div className="flex items-start justify-between mb-4">
              <div>
                <h3 className="text-2xl font-bold text-foreground mb-2">{currentLocation?.name}</h3>
                <p className="text-muted-foreground">{currentLocation?.description}</p>
              </div>
              <Button variant="outline">
                <Icon name="Calendar" size={16} className="mr-2" />
                Schedule Visit
              </Button>
            </div>

            <div className="flex flex-wrap gap-3">
              <Button variant="ghost" size="sm">
                <Icon name="Share2" size={16} className="mr-2" />
                Share Tour
              </Button>
              <Button variant="ghost" size="sm">
                <Icon name="Download" size={16} className="mr-2" />
                Download Map
              </Button>
              <Button variant="ghost" size="sm">
                <Icon name="Info" size={16} className="mr-2" />
                Accessibility Info
              </Button>
            </div>
          </div>
        </div>
      </div>
    </section>);

};

export default VirtualTourSection;