import React, { useState, useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';

gsap?.registerPlugin(ScrollTrigger);

const InteractiveCampusMap = () => {
  const [selectedBuilding, setSelectedBuilding] = useState(null);
  const [mapView, setMapView] = useState('overview');
  const sectionRef = useRef(null);
  const mapRef = useRef(null);

  const buildings = [
    {
      id: 'main-building',
      name: 'Main Academic Building',
      x: 45,
      y: 30,
      type: 'academic',
      floors: 5,
      facilities: ['Lecture Halls', 'Faculty Offices', 'Administration', 'Library'],
      description: 'The heart of our academic activities with modern classrooms and administrative offices.',
      capacity: '2,000 students',
      features: ['WiFi Coverage', 'Air Conditioning', 'Elevator Access', 'Cafeteria']
    },
    {
      id: 'science-lab',
      name: 'Science Laboratory Complex',
      x: 25,
      y: 45,
      type: 'laboratory',
      floors: 3,
      facilities: ['Chemistry Labs', 'Physics Labs', 'Biology Labs', 'Research Centers'],
      description: 'State-of-the-art laboratories equipped with the latest scientific instruments.',
      capacity: '500 students',
      features: ['Fume Hoods', 'Safety Equipment', 'Digital Microscopes', 'Clean Rooms']
    },
    {
      id: 'library',
      name: 'Digital Learning Library',
      x: 65,
      y: 25,
      type: 'library',
      floors: 4,
      facilities: ['Study Areas', 'Computer Lab', 'Archives', 'Meeting Rooms'],
      description: 'Comprehensive library with digital resources and collaborative study spaces.',
      capacity: '800 students',
      features: ['24/7 Access', 'Silent Zones', 'Group Study Rooms', 'Printing Services']
    },
    {
      id: 'sports-center',
      name: 'Sports & Recreation Center',
      x: 75,
      y: 60,
      type: 'sports',
      floors: 2,
      facilities: ['Gymnasium', 'Swimming Pool', 'Fitness Center', 'Sports Courts'],
      description: 'Complete sports facility promoting health and wellness among students.',
      capacity: '300 students',
      features: ['Modern Equipment', 'Locker Rooms', 'First Aid', 'Personal Training']
    },
    {
      id: 'student-center',
      name: 'Student Activity Center',
      x: 35,
      y: 65,
      type: 'student',
      floors: 3,
      facilities: ['Cafeteria', 'Student Lounge', 'Event Hall', 'Bookstore'],
      description: 'Central hub for student activities, dining, and social interactions.',
      capacity: '1,000 students',
      features: ['Food Court', 'ATM Services', 'Event Spaces', 'Student Services']
    },
    {
      id: 'innovation-hub',
      name: 'Innovation & Technology Hub',
      x: 55,
      y: 50,
      type: 'technology',
      floors: 4,
      facilities: ['Computer Labs', 'Maker Space', 'VR Lab', 'Startup Incubator'],
      description: 'Cutting-edge technology center fostering innovation and entrepreneurship.',
      capacity: '400 students',
      features: ['3D Printers', 'VR Equipment', 'High-Speed Internet', 'Collaboration Tools']
    }
  ];

  const mapViews = [
    { id: 'overview', name: 'Campus Overview', icon: 'Map' },
    { id: 'academic', name: 'Academic Buildings', icon: 'GraduationCap' },
    { id: 'facilities', name: 'Facilities', icon: 'Building' },
    { id: 'accessibility', name: 'Accessibility', icon: 'Accessibility' }
  ];

  useEffect(() => {
    const ctx = gsap?.context(() => {
      gsap?.fromTo(sectionRef?.current,
        { opacity: 0, y: 50 },
        {
          opacity: 1,
          y: 0,
          duration: 1,
          scrollTrigger: {
            trigger: sectionRef?.current,
            start: "top 80%",
            toggleActions: "play none none reverse"
          }
        }
      );

      gsap?.fromTo(".map-building",
        { scale: 0, opacity: 0 },
        {
          scale: 1,
          opacity: 1,
          duration: 0.5,
          stagger: 0.1,
          scrollTrigger: {
            trigger: mapRef?.current,
            start: "top 85%",
            toggleActions: "play none none reverse"
          }
        }
      );
    }, sectionRef);

    return () => ctx?.revert();
  }, []);

  const getBuildingColor = (type) => {
    const colors = {
      academic: 'bg-primary',
      laboratory: 'bg-accent',
      library: 'bg-secondary',
      sports: 'bg-success',
      student: 'bg-warning',
      technology: 'bg-purple-500'
    };
    return colors?.[type] || 'bg-muted';
  };

  const getBuildingIcon = (type) => {
    const icons = {
      academic: 'GraduationCap',
      laboratory: 'Microscope',
      library: 'BookOpen',
      sports: 'Dumbbell',
      student: 'Users',
      technology: 'Cpu'
    };
    return icons?.[type] || 'Building';
  };

  return (
    <section ref={sectionRef} className="py-20 bg-card">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold text-gradient mb-6">Interactive Campus Map</h2>
          <p className="text-xl text-muted-foreground max-w-3xl mx-auto">
            Navigate our campus with ease. Click on any building to explore facilities, get directions, and discover what makes each space special.
          </p>
        </div>

        {/* Map View Controls */}
        <div className="flex flex-wrap justify-center gap-4 mb-8">
          {mapViews?.map((view) => (
            <button
              key={view?.id}
              onClick={() => setMapView(view?.id)}
              className={`flex items-center space-x-2 px-4 py-2 rounded-lg border transition-all duration-300 ${
                mapView === view?.id
                  ? 'border-primary bg-primary text-primary-foreground shadow-brand-sm'
                  : 'border-border bg-background text-foreground hover:border-primary/50'
              }`}
            >
              <Icon name={view?.icon} size={16} />
              <span className="text-sm font-medium">{view?.name}</span>
            </button>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Interactive Map */}
          <div className="lg:col-span-2">
            <div className="bg-background rounded-2xl shadow-brand-lg overflow-hidden">
              <div className="p-4 border-b border-border">
                <div className="flex items-center justify-between">
                  <h3 className="text-lg font-semibold text-foreground">Campus Layout</h3>
                  <div className="flex space-x-2">
                    <Button variant="ghost" size="sm">
                      <Icon name="ZoomIn" size={16} />
                    </Button>
                    <Button variant="ghost" size="sm">
                      <Icon name="ZoomOut" size={16} />
                    </Button>
                    <Button variant="ghost" size="sm">
                      <Icon name="Download" size={16} />
                    </Button>
                  </div>
                </div>
              </div>
              
              <div ref={mapRef} className="relative aspect-video bg-gradient-to-br from-green-50 to-blue-50 p-8">
                {/* Campus Paths */}
                <svg className="absolute inset-0 w-full h-full" style={{ zIndex: 1 }}>
                  <path
                    d="M 10% 80% Q 50% 60% 90% 40%"
                    stroke="#e2e8f0"
                    strokeWidth="3"
                    fill="none"
                    strokeDasharray="5,5"
                  />
                  <path
                    d="M 20% 20% Q 60% 40% 80% 80%"
                    stroke="#e2e8f0"
                    strokeWidth="3"
                    fill="none"
                    strokeDasharray="5,5"
                  />
                </svg>

                {/* Buildings */}
                {buildings?.map((building) => (
                  <button
                    key={building?.id}
                    onClick={() => setSelectedBuilding(building)}
                    className={`map-building absolute w-12 h-12 rounded-lg shadow-brand-md border-2 border-white hover:scale-110 transition-all duration-300 ${getBuildingColor(building?.type)} ${
                      selectedBuilding?.id === building?.id ? 'ring-4 ring-primary/30 scale-110' : ''
                    }`}
                    style={{ 
                      left: `${building?.x}%`, 
                      top: `${building?.y}%`,
                      zIndex: selectedBuilding?.id === building?.id ? 10 : 2
                    }}
                  >
                    <Icon name={getBuildingIcon(building?.type)} size={20} color="white" className="mx-auto" />
                  </button>
                ))}

                {/* Building Labels */}
                {buildings?.map((building) => (
                  <div
                    key={`label-${building?.id}`}
                    className="absolute text-xs font-medium text-foreground bg-background/90 backdrop-blur-sm px-2 py-1 rounded-md shadow-sm pointer-events-none"
                    style={{ 
                      left: `${building?.x}%`, 
                      top: `${building?.y + 8}%`,
                      transform: 'translateX(-50%)',
                      zIndex: 3
                    }}
                  >
                    {building?.name}
                  </div>
                ))}

                {/* Legend */}
                <div className="absolute bottom-4 left-4 bg-background/95 backdrop-blur-sm rounded-lg p-4 shadow-brand-md">
                  <h4 className="text-sm font-semibold text-foreground mb-2">Legend</h4>
                  <div className="space-y-2">
                    {Object.entries({
                      academic: 'Academic',
                      laboratory: 'Laboratory',
                      library: 'Library',
                      sports: 'Sports',
                      student: 'Student Center',
                      technology: 'Technology'
                    })?.map(([type, label]) => (
                      <div key={type} className="flex items-center space-x-2 text-xs">
                        <div className={`w-3 h-3 rounded ${getBuildingColor(type)}`}></div>
                        <span>{label}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Building Information Panel */}
          <div className="space-y-6">
            {selectedBuilding ? (
              <div className="bg-background rounded-2xl shadow-brand-lg p-6">
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h3 className="text-xl font-bold text-foreground mb-2">{selectedBuilding?.name}</h3>
                    <div className="flex items-center space-x-4 text-sm text-muted-foreground">
                      <span>{selectedBuilding?.floors} floors</span>
                      <span>{selectedBuilding?.capacity}</span>
                    </div>
                  </div>
                  <div className={`w-12 h-12 rounded-lg ${getBuildingColor(selectedBuilding?.type)} flex items-center justify-center`}>
                    <Icon name={getBuildingIcon(selectedBuilding?.type)} size={20} color="white" />
                  </div>
                </div>
                
                <p className="text-muted-foreground mb-6">{selectedBuilding?.description}</p>
                
                <div className="space-y-4">
                  <div>
                    <h4 className="font-semibold text-foreground mb-2">Facilities</h4>
                    <div className="grid grid-cols-2 gap-2">
                      {selectedBuilding?.facilities?.map((facility, index) => (
                        <div key={index} className="text-sm bg-muted text-muted-foreground px-2 py-1 rounded">
                          {facility}
                        </div>
                      ))}
                    </div>
                  </div>
                  
                  <div>
                    <h4 className="font-semibold text-foreground mb-2">Features</h4>
                    <div className="space-y-1">
                      {selectedBuilding?.features?.map((feature, index) => (
                        <div key={index} className="flex items-center space-x-2 text-sm">
                          <Icon name="Check" size={12} className="text-success" />
                          <span>{feature}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
                
                <div className="flex space-x-3 mt-6">
                  <Button variant="default" size="sm" fullWidth>
                    <Icon name="Navigation" size={14} className="mr-2" />
                    Get Directions
                  </Button>
                  <Button variant="outline" size="sm">
                    <Icon name="Calendar" size={14} className="mr-2" />
                    Book Space
                  </Button>
                </div>
              </div>
            ) : (
              <div className="bg-background rounded-2xl shadow-brand-lg p-6 text-center">
                <div className="w-16 h-16 bg-muted rounded-full flex items-center justify-center mx-auto mb-4">
                  <Icon name="MapPin" size={24} className="text-muted-foreground" />
                </div>
                <h3 className="text-lg font-semibold text-foreground mb-2">Select a Building</h3>
                <p className="text-muted-foreground text-sm">
                  Click on any building on the map to view detailed information about facilities and features.
                </p>
              </div>
            )}

            {/* Quick Actions */}
            <div className="bg-background rounded-2xl shadow-brand-lg p-6">
              <h3 className="text-lg font-semibold text-foreground mb-4">Quick Actions</h3>
              <div className="space-y-3">
                <Button variant="ghost" fullWidth className="justify-start">
                  <Icon name="Download" size={16} className="mr-3" />
                  Download Campus Map
                </Button>
                <Button variant="ghost" fullWidth className="justify-start">
                  <Icon name="Navigation" size={16} className="mr-3" />
                  Campus Directions
                </Button>
                <Button variant="ghost" fullWidth className="justify-start">
                  <Icon name="Phone" size={16} className="mr-3" />
                  Emergency Contacts
                </Button>
                <Button variant="ghost" fullWidth className="justify-start">
                  <Icon name="Info" size={16} className="mr-3" />
                  Visitor Information
                </Button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default InteractiveCampusMap;