import React, { useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import Icon from '../../../components/AppIcon';
import Image from '../../../components/AppImage';
import Button from '../../../components/ui/Button';

const FacilityHero = () => {
  const heroRef = useRef(null);
  const contentRef = useRef(null);
  const imageRef = useRef(null);

  useEffect(() => {
    const ctx = gsap?.context(() => {
      const tl = gsap?.timeline();

      tl?.fromTo(contentRef?.current,
      { opacity: 0, y: 50 },
      { opacity: 1, y: 0, duration: 1, ease: "power3.out" }
      )?.fromTo(imageRef?.current,
      { opacity: 0, scale: 0.9 },
      { opacity: 1, scale: 1, duration: 1, ease: "power3.out" },
      "-=0.5"
      )?.fromTo(".hero-stat",
      { opacity: 0, y: 20 },
      { opacity: 1, y: 0, duration: 0.6, stagger: 0.1 },
      "-=0.3"
      );
    }, heroRef);

    return () => ctx?.revert();
  }, []);

  const stats = [
  { icon: 'Building2', value: '15+', label: 'Modern Buildings' },
  { icon: 'Users', value: '5,000+', label: 'Study Spaces' },
  { icon: 'Zap', value: '24/7', label: 'Access Available' },
  { icon: 'Award', value: '100%', label: 'Accessible Design' }];


  return (
    <section ref={heroRef} className="relative min-h-screen flex items-center bg-gradient-to-br from-background via-card to-background overflow-hidden">
      {/* Background Pattern */}
      <div className="absolute inset-0 opacity-5">
        <div className="absolute inset-0 bg-gradient-to-r from-primary to-accent"></div>
      </div>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
          {/* Content */}
          <div ref={contentRef} className="space-y-8">
            <div className="space-y-6">
              <div className="inline-flex items-center space-x-2 bg-primary/10 text-primary px-4 py-2 rounded-full text-sm font-medium">
                <Icon name="MapPin" size={16} />
                <span>Campus Facilities</span>
              </div>
              
              <h1 className="text-5xl lg:text-6xl font-bold text-gradient leading-tight">
                World-Class Learning
                <span className="block text-foreground">Environment</span>
              </h1>
              
              <p className="text-xl text-muted-foreground leading-relaxed max-w-xl">
                Discover our state-of-the-art facilities designed to inspire learning, foster collaboration, and support your academic journey. From cutting-edge laboratories to comfortable study spaces, every corner is crafted for your success.
              </p>
            </div>

            <div className="flex flex-col sm:flex-row gap-4">
              <Button variant="default" size="lg" className="bg-gradient-accent hover:shadow-glow-accent">
                <Icon name="Play" size={18} className="mr-2" />
                Take Virtual Tour
              </Button>
              <Button variant="outline" size="lg">
                <Icon name="Calendar" size={18} className="mr-2" />
                Schedule Visit
              </Button>
              <Button variant="ghost" size="lg">
                <Icon name="Download" size={18} className="mr-2" />
                Campus Map
              </Button>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-6 pt-8">
              {stats?.map((stat, index) =>
              <div key={index} className="hero-stat text-center">
                  <div className="w-12 h-12 bg-primary/10 rounded-lg flex items-center justify-center mx-auto mb-3">
                    <Icon name={stat?.icon} size={20} className="text-primary" />
                  </div>
                  <div className="text-2xl font-bold text-foreground">{stat?.value}</div>
                  <div className="text-sm text-muted-foreground">{stat?.label}</div>
                </div>
              )}
            </div>
          </div>

          {/* Hero Image */}
          <div ref={imageRef} className="relative">
            <div className="relative rounded-2xl overflow-hidden shadow-brand-xl">
              <Image
                src="https://images.unsplash.com/photo-1588959293268-484c415422d8"
                alt="Modern university campus building with glass facade, students walking on pathways, and green landscaping"
                className="w-full h-[600px] object-cover" />

              
              {/* Overlay Content */}
              <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent"></div>
              
              {/* Floating Cards */}
              <div className="absolute top-6 right-6 bg-background/95 backdrop-blur-sm rounded-lg p-4 shadow-brand-md">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-success/10 rounded-lg flex items-center justify-center">
                    <Icon name="Wifi" size={18} className="text-success" />
                  </div>
                  <div>
                    <div className="font-semibold text-sm">Free WiFi</div>
                    <div className="text-xs text-muted-foreground">Campus-wide</div>
                  </div>
                </div>
              </div>
              
              <div className="absolute bottom-6 left-6 bg-background/95 backdrop-blur-sm rounded-lg p-4 shadow-brand-md">
                <div className="flex items-center space-x-3">
                  <div className="w-10 h-10 bg-primary/10 rounded-lg flex items-center justify-center">
                    <Icon name="Shield" size={18} className="text-primary" />
                  </div>
                  <div>
                    <div className="font-semibold text-sm">Secure Access</div>
                    <div className="text-xs text-muted-foreground">24/7 Security</div>
                  </div>
                </div>
              </div>
            </div>

            {/* Decorative Elements */}
            <div className="absolute -top-4 -left-4 w-24 h-24 bg-accent/20 rounded-full blur-xl animate-float"></div>
            <div className="absolute -bottom-4 -right-4 w-32 h-32 bg-primary/20 rounded-full blur-xl animate-float" style={{ animationDelay: '2s' }}></div>
          </div>
        </div>
      </div>
      {/* Scroll Indicator */}
      <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 animate-bounce">
        <div className="w-6 h-10 border-2 border-muted-foreground rounded-full flex justify-center">
          <div className="w-1 h-3 bg-muted-foreground rounded-full mt-2 animate-pulse"></div>
        </div>
      </div>
    </section>);

};

export default FacilityHero;